/* V1.9: slideshow cinematografico exclusivo ao fundo da HOME; jogo e menus inalterados. */
#home{isolation:isolate}
#home-cinema{position:absolute;inset:0;z-index:0;overflow:hidden;pointer-events:none;background:#090d10;opacity:0;transition:opacity .3s ease}
#home-cinema.ready{opacity:1}
#home-cinema .home-cinema-frame{position:absolute;inset:-1.5%;opacity:0;transition:opacity 1650ms ease-in-out;will-change:opacity}
#home-cinema .home-cinema-picture{position:absolute;inset:0;background-repeat:no-repeat;background-size:cover;background-position:50% 50%;animation:cinema-pan-left 11.5s linear both;will-change:transform}
#home-cinema .home-cinema-frame.moving-right .home-cinema-picture{animation-name:cinema-pan-right}
#home-cinema .home-cinema-frame.moving-zoom .home-cinema-picture{animation-name:cinema-zoom}
@keyframes cinema-pan-left{from{transform:scale(1.065) translate3d(0.8%,.3%,0)}to{transform:scale(1.13) translate3d(-1.2%,-.35%,0)}}
@keyframes cinema-pan-right{from{transform:scale(1.12) translate3d(-1%,0,0)}to{transform:scale(1.055) translate3d(1%,.35%,0)}}
@keyframes cinema-zoom{from{transform:scale(1.06) translate3d(0,.5%,0)}to{transform:scale(1.145) translate3d(0,-.6%,0)}}
#home-cinema .home-cinema-shade{position:absolute;inset:0;z-index:4;background:linear-gradient(90deg,rgba(7,10,10,.97) 0%,rgba(7,10,10,.93) 29%,rgba(7,10,10,.71) 43%,rgba(7,10,10,.20) 69%,rgba(7,10,10,.17) 100%),linear-gradient(0deg,#0b0e10dd 0%,transparent 30%,transparent 72%,#0b0e1099 100%)}
#home-cinema .home-cinema-title{position:absolute;z-index:2;right:6%;bottom:32%;width:36%;display:flex;flex-direction:column;align-items:flex-end;gap:5px;text-align:right;filter:drop-shadow(0 3px 12px #000e)}
#home-cinema .home-cinema-title .cinema-scene{font:600 9px 'Barlow',Arial,sans-serif;color:#c6c9be;letter-spacing:3px;text-transform:uppercase;border-bottom:1px solid var(--cinema-accent,#ff773d);padding-bottom:6px}
#home-cinema .home-cinema-title strong{font:800 clamp(31px,4.4vw,74px)/.96 'Barlow Condensed',Impact,sans-serif;color:#f5eee1;letter-spacing:1px;text-transform:uppercase;transform:skew(-6deg);transform-origin:right center;text-shadow:0 5px 20px #000d}
#home-cinema .home-cinema-title small{font:700 clamp(9px,1.15vw,16px) 'Barlow Condensed',Arial,sans-serif;letter-spacing:2px;background:var(--cinema-accent,#ff773d);color:#10110d;text-transform:uppercase;padding:5px 11px;clip-path:polygon(0 0,100% 0,100% 100%,8px 100%)}
#home>.home-copy,#home>.hero-label,#home>.vertical-label,#home>.home-footer{z-index:5}
@media(max-width:800px){#home-cinema .home-cinema-title{right:5%;bottom:24%;width:52%}#home-cinema .home-cinema-title strong{font-size:clamp(29px,6vw,48px)}#home-cinema .home-cinema-shade{background:linear-gradient(90deg,#070a0bee 0%,#070a0bb8 38%,#070a0b30 78%),linear-gradient(0deg,#080b0ccf,transparent 37%,transparent 63%,#080b0c8c)}}
@media(max-width:600px) and (orientation:portrait){#home-cinema .home-cinema-picture{background-position:70% center}#home-cinema .home-cinema-title{right:5%;left:auto;bottom:17%;width:60%}#home-cinema .home-cinema-title strong{font-size:clamp(33px,9vw,56px)}#home-cinema .home-cinema-shade{background:linear-gradient(0deg,#090d0f 0%,#090d0fbf 21%,transparent 48%,#090d0f70 79%,#090d0fe3 100%),linear-gradient(90deg,#090d0f91,transparent 85%)}#home-cinema .home-cinema-frame{inset:-1%}}
