/* V2.4: icone vetorial no cabeçalho e cronometro visível da protecao em combate. */
#settings-open{display:grid;place-items:center;line-height:1;flex:0 0 36px;padding:0;overflow:hidden}
#settings-open svg{display:block;flex:none;width:19px;height:19px;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linejoin:round;stroke-linecap:round}
.touch-controls .pad-button.power[data-active]:not([data-active=""])::before{
 content:"DEF " attr(data-active);position:absolute;top:-24px;left:50%;transform:translateX(-50%);
 border:1px solid #9ed8cb;background:#133e34f0;border-radius:5px;padding:3px 6px;
 color:#bff5d7;font:700 10px/1.1 'Barlow Condensed',sans-serif;white-space:nowrap;box-shadow:0 2px 10px #0008;
}

