.mk-mp-fighter strong{position:absolute;bottom:0;left:0;right:0;padding:6px 5px 7px;background:#0c130dea;font:700 11px 'Barlow Condensed';white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
